const BRIEF_LEVELS=new Set([5,6,9,10,16,17,18,20,24,25,26,27,28,29,30]);
function svgShell(body,cls=''){return `<svg class="activity-svg ${cls}" viewBox="0 0 520 200" role="img" aria-label="交互实验示意图">${body}</svg>`}
function pixelThumb(img,color='#567b69'){return `<svg viewBox="0 0 80 80" aria-label="手绘样本">${img.map((v,i)=>`<rect x="${i%8*10}" y="${Math.floor(i/8)*10}" width="9" height="9" fill="${v?color:'#e8eadb'}"/>`).join('')}</svg>`}
function graphTrace(history){let a=history.slice(-60),hi=Math.max(...a,1e-6);return `<svg viewBox="0 0 240 65" aria-label="实际训练损失曲线"><path d="M5 5v50h230" fill="none" stroke="#c4ceb7"/><polyline points="${a.map((v,i)=>(5+i*230/Math.max(1,a.length-1))+','+(55-Math.min(1,v/hi)*45)).join(' ')}" fill="none" stroke="#779e65" stroke-width="2.5"/></svg>`}
function activityArt(l,mood='think'){let type=l.engine,id=l.id||1,b='';
 if(type==='rules')b=`<path d="M35 103h285" stroke="#91a893" stroke-width="29" stroke-linecap="round"/><path class="belt-marks" d="M35 103h285" stroke="#d9e0c7" stroke-width="3" stroke-dasharray="4 20"/>${[0,1,0,1].map((c,i)=>fruitArt(c,66+i*57,80,.55)).join('')}<path d="M318 103q45-60 123-52m-123 52q45 60 123 52" fill="none" stroke="#9aad85" stroke-width="4"/><rect x="406" y="24" width="75" height="43" rx="11" fill="#bbd491"/><rect x="406" y="131" width="75" height="43" rx="11" fill="#edbe85"/>`;
 else if(type==='knn'){let points=Array.from({length:11},(_,i)=>({x:80+(i*67+id*9)%350,y:35+(i*43)%126}));b=points.map((p,i)=>`<path class="radar-link" style="animation-delay:${i*.13}s" d="M260 100L${p.x} ${p.y}" stroke="${i%2?'#dbac79':'#93b174'}" stroke-dasharray="5 4"/>${fruitArt(i%2,p.x,p.y,.45)}`).join('')+'<circle class="radar-ring" cx="260" cy="100" r="36" fill="none" stroke="#84acb8" stroke-width="2"/><circle cx="260" cy="100" r="12" fill="#f9f7dc" stroke="#7392a0"/>'}
 else if(type==='reg')b=`<path d="M45 162h420M65 175V28" fill="none" stroke="#aebba0" stroke-width="2"/><path d="M75 148L440 46" stroke="#688c5d" stroke-width="3"/><g class="prediction-stars">${[0,1,2,3,4].map(i=>`<circle cx="${100+i*73}" cy="${141-i*23+(i%2)*8}" r="7" fill="#e7b35c"/>`).join('')}</g><g class="tiny-launch"><path d="M63 143l23-8-9 21z" fill="#c88566"/><path d="M66 151l-13 8" stroke="#edbd68" stroke-width="5"/></g>`;
 else if(type==='tree')b=`<g stroke="#93a778" stroke-width="4" fill="none"><path d="M250 38v28L120 111m130-45 130 45M120 111l-55 54m55-54 55 54M380 111l-55 54m55-54 55 54"/></g>${[[250,38],[120,111],[380,111],[65,165],[175,165],[325,165],[435,165]].map((p,i)=>`<rect class="gate-light" style="animation-delay:${i*.2}s" x="${p[0]-22}" y="${p[1]-15}" width="44" height="30" rx="9" fill="${i>2?'#e9cfaa':'#bcd49b'}" stroke="#7b9367"/>`).join('')}`;
 else if(type==='nn'){let layers=id===11?[[100,2],[420,1]]:[[70,2],[260,id===13?5:3],[450,1]],nodes=layers.map(([x,n])=>Array.from({length:n},(_,i)=>({x,y:100+(i-(n-1)/2)*31})));b=nodes.slice(0,-1).map((layer,j)=>layer.map(p=>nodes[j+1].map(q=>`<path class="synapse-flow" d="M${p.x+12} ${p.y}L${q.x-12} ${q.y}" fill="none" stroke="#b4a8d0" stroke-width="2"/>`).join('')).join('')).join('')+nodes.map((layer,j)=>layer.map((p,i)=>`<circle class="neuron-pulse" style="animation-delay:${j*.3+i*.1}s" cx="${p.x}" cy="${p.y}" r="12" fill="#c6dcb3" stroke="#698465" stroke-width="3"/>`).join('')).join('')}
 else if(type==='conv')b=`${Array.from({length:48},(_,i)=>`<rect x="${45+i%8*21}" y="${25+Math.floor(i/8)*24}" width="18" height="21" fill="${((i%8>3)!==(id===18))?'#6f8f7a':'#dce6c9'}"/>`).join('')}<rect class="lens-travel" x="45" y="25" width="63" height="72" fill="#e4b26c" fill-opacity="0.208" stroke="#c28a54" stroke-width="3"/><path d="M244 98h52" stroke="#9aa889" stroke-width="3"/><path d="M285 89l12 9-12 9" fill="none" stroke="#9aa889" stroke-width="3"/>${Array.from({length:24},(_,i)=>`<rect x="${329+i%6*23}" y="${47+Math.floor(i/6)*25}" width="20" height="22" fill="${i%6===2?'#dfad73':'#dbe3d0'}"/>`).join('')}`;
 else if(type==='vision')b=`<rect x="90" y="28" width="130" height="142" rx="12" fill="#fff9e8" stroke="#c3caaa"/><rect class="picture-shift" x="315" y="38" width="124" height="130" rx="12" fill="#f8f9ed" stroke="#c3caaa"/>${Array.from({length:8},(_,i)=>`<rect class="pixel-light" style="animation-delay:${i*.12}s" x="${120+(i%3)*24}" y="${57+Math.floor(i/3)*27}" width="20" height="22" fill="${i%2?'#90b69b':'#dabb93'}"/>`).join('')}<path d="M343 73h66v19h-66z" fill="#a5bea3"/>`;
 else if(type==='rl')b=`<path d="M45 160V51h117v72h105V47h112v111h90" fill="none" stroke="#c8d7b1" stroke-width="35"/><path class="route-trace" d="M45 160V51h117v72h105V47h112v111h90" fill="none" stroke="#73905d" stroke-width="4" stroke-dasharray="7 9"/><path d="M455 144l15-15 15 15-15 25z" fill="#edc565"/><g class="rover-mini" transform="translate(20 136)"><rect width="40" height="21" rx="6" fill="#f7f3dc" stroke="#73905d"/><circle cx="8" cy="22" r="6" fill="#68825a"/><circle cx="31" cy="22" r="6" fill="#68825a"/></g>`;
 else if(type==='agent')b=`${['打开','整理','保存'].map((t,i)=>`<g class="instruction-pop" style="animation-delay:${i*.35}s"><rect x="${65+i*140}" y="54" width="106" height="87" rx="13" fill="#f9f8e7" stroke="#b4c1a3" stroke-width="2"/><rect x="${92+i*140}" y="68" width="45" height="39" rx="5" fill="${['#c9dbaa','#dcc6a6','#acd0c6'][i]}"/><text x="${118+i*140}" y="126" text-anchor="middle" font-size="13" fill="#617652">${t}</text></g>`).join('')}`;
 else b=`<rect x="147" y="20" width="226" height="160" rx="14" fill="#e1c298"/>${Array.from({length:5},(_,i)=>`<path d="M169 ${38+i*31}h181M${169+i*45} 38v124" stroke="#9b805d"/>`).join('')}<circle cx="214" cy="69" r="12" fill="#314b3e"/><circle cx="305" cy="100" r="12" fill="#fff9e7"/><circle class="stone-arrive" cx="259" cy="100" r="12" fill="#314b3e"/>`;
 return svgShell(`<rect width="520" height="200" rx="20" fill="${WORLDS[l.chapter][2]}"/>${b}`,`lesson-motion mode-${l.engine}`);
}
function activityMarkup(){let s=Engine.s;if(labMode)return '';let html='';
 if(s.type==='rules'){html=`<div class="sorting-belt">${s.test.slice(0,8).map((p,i)=>`<span class="parcel ${Engine.predict(p)===p.c?'sorted':'misroute'}" style="--i:${i};--lane:${Engine.predict(p)?'30px':'-30px'}">${p.c?'🍊':'🍏'}<small>→ ${Engine.predict(p)?'橘子篮':'苹果篮'}</small></span>`).join('')}</div><div class="belt-destinations"><span>🍏 苹果篮</span><span>🍊 橘子篮</span></div><p class="activity-note">滑动下方分界线，观察这些新水果会被送到哪只篮子。</p>`}
 if(s.type==='knn'&&s.v==='features')html=`<div class="sensor-deck"><button onclick="setParam('feature',0)" class="${!s.feature?'selected':''}">🎲<b>编号扫描器</b><small>读取随机编号</small></button><button onclick="setParam('feature',1)" class="${s.feature?'selected':''}">⚖<b>特征扫描器</b><small>读取重量与甜度</small></button></div>`;
 if(s.type==='knn'&&s.v==='vote'){let q=s.query,list=s.train.map(p=>({p,d:(p.x-q.x)**2+(p.y-q.y)**2})).sort((a,b)=>a.d-b.d).slice(0,s.k);html=`<div class="voting-booth">${list.map(({p},i)=>`<span class="vote-card" style="--i:${i}">${p.c?'🍊':'🍏'}<small>邻居 ${i+1}</small></span>`).join('')}<strong>投票结果：${Engine.predict(q)?'橘子':'苹果'}</strong></div>`}
 if(s.type==='knn'&&s.v==='dirty'){let original=Algo.data('clusters',24,12);html=`<div class="audit-desk">${s.train.slice(0,9).map((p,i)=>`<button class="audit-card ${p.c===original[i].c?'verified':''}" onclick="auditRecord(${i})"><small>档案 ${String(i+1).padStart(2,'0')}</small><b>${p.c?'🍊':'🍏'}</b><span>${p.c===original[i].c?'已核对 ✓':'查看原始记录'}</span></button>`).join('')}</div>`}
 if(s.type==='reg'&&s.v==='overfit'){let train=Algo.mean(s.train.map(p=>(Engine.predict(p)-p.y)**2)),test=Engine.metric().value;html=`<div class="exam-deck"><div><small>模型见过的训练题</small><b>误差 ${train.toFixed(3)}</b><span>这张成绩单够吗？</span></div><button class="${s.revealTest?'revealed':''}" onclick="revealExam()"><small>模型没见过的新题</small><b>${s.revealTest?'误差 '+test.toFixed(3):'？'}</b><span>${s.revealTest?'比较两张成绩单':'点击翻开新题卡'}</span></button></div>`}
 else if(s.type==='reg'){let x=.7,target=.68*x+.16,pred=Engine.predict({x}),loc=Math.max(22,Math.min(492,55+pred*430)),goal=55+target*430;html=`<div class="launch-field ${s.shot?'shot-fired':''}" style="--landing:${loc}px"><svg viewBox="0 0 520 130" aria-label="预测落点与目标"><path d="M30 95h460" stroke="#c5d0b5" stroke-width="2"/><circle cx="${goal}" cy="73" r="23" fill="#e6b96d" fill-opacity="0.267" stroke="#d5a24e" stroke-width="2"/><circle cx="${goal}" cy="73" r="7" fill="#d5a24e"/><path d="M30 88Q${loc*.45} -6 ${loc} 73" fill="none" stroke="#7b9b6b" stroke-dasharray="5 6"/><g class="forecast-arrow"><path d="M${loc-10} 70l20 3-20 7 4-5z" fill="#597b58"/></g><text x="${goal}" y="116" text-anchor="middle" fill="#9d7b42" font-size="12">真实目标 ${target.toFixed(2)}</text><text x="30" y="18" fill="#66805e" font-size="12">当前预测 ${pred.toFixed(2)} · 偏差 ${Math.abs(pred-target).toFixed(2)}</text></svg></div><div class="activity-actions"><button class="secondary" onclick="firePrediction()">➶ 用当前模型试射</button>${s.history.length?graphTrace(s.history):'<small>调整参数后再试一次，比较预测落点。</small>'}</div>`}
 if(s.type==='tree'){let p=s.probe||{x:.7,y:.7},xpass=p.x>s.tx,ypass=p.y>s.ty;html=`<div class="gate-route"><button onclick="treeProbe(.7,.7)">右上点</button><button onclick="treeProbe(.7,.3)">右下点</button><button onclick="treeProbe(.3,.7)">左上点</button><div class="branch-step active">x = ${p.x} &gt; ${s.tx.toFixed(2)}？<b>${xpass?'是 ↓':'否 → A'}</b></div><div class="branch-step ${xpass?'active':''}">y = ${p.y} &gt; ${s.ty.toFixed(2)}？<b>${xpass?(ypass?'是 → B':'否 → A'):'本次不经过这里'}</b></div></div>`}
 if(s.type==='nn')html=`<div class="circuit-kit"><span>输入 2</span><span>→</span><button onclick="setParam('hidden',${s.hidden?Math.min(12,s.hidden+4):4})">${s.hidden?s.hidden+' 个隐藏节点':'空插槽 · 点此加层'} <b>＋</b></button><span>→ 输出 1</span><button class="small-link" onclick="showBrain()">查看连接</button></div>`;
 if(s.type==='conv'){let i=s.scanIndex||0;html=`<div class="lens-instruction">✋ 在左图上拖动取样框，观察右图对应位置。<b>当前响应：${s.out[i]===undefined?'待扫描':s.out[i].toFixed(2)}</b></div>`}
 if(s.type==='vision'){html=`<div class="sample-film">${s.samples.slice(-6).map(p=>`<div>${pixelThumb(p.img,p.c?'#c89468':'#658765')}<small>${p.c?'B · 横线':'A · 竖线'}</small></div>`).join('')||'<small>你的样本会保存在这里。按住画布拖动，可以连续绘画。</small>'}</div>`;if(s.aug&&s.samples.length)html+=`<div class="augmentation-film">${[-1,0,1].map(dx=>pixelThumb(Algo.shift(s.samples[0].img,dx,0))).join('<span>→</span>')}<small>同一个图案，换几个位置</small></div>`}
 if(s.type==='rl')html=`<div class="manual-explorer"><span>先亲自探路，看看哪些动作有用。</span><div>${[['↑',0],['→',1],['↓',2],['←',3]].map(([t,a])=>`<button aria-label="手动移动 ${t}" onclick="walkManually(${a})">${t}</button>`).join('')}</div><small>${s.manualNote||'点击方向键试走；训练时会重新从起点开始。'}</small></div>`;
 if(s.type==='agent')html=`<div class="command-builder"><small>先排一遍你的指令，再和智能体比较</small><div class="command-options">${['打开','整理','保存'].map((x,i)=>`<button onclick="queueCommand(${i})">${x}</button>`).join('')}</div><div class="command-strip">${(s.queue||[]).map((a,i)=>`<span>${i+1}. ${['打开','整理','保存'][a]}</span>`).join(' → ')||'等待你的第一条指令…'}</div><button class="secondary" onclick="runCommands()">运行我的指令</button><button onclick="clearCommands()">清空</button></div>`;
 if(phase===1||guideBusy)html=html.replace(/<button /g,'<button disabled ');return html?`<section id="activity-stage" class="activity-stage activity-${s.type}">${html}</section>`:'';
}
const priorEngineHTML=Engine.html.bind(Engine);Engine.html=function(){let html=priorEngineHTML();if(labMode)return html;html=html.replace('<div class="stage">','<div class="stage">'+activityMarkup());if(['rules','tree'].includes(this.s.type)||(this.s.type==='reg'&&['manual','overfit'].includes(this.s.v)))html=html.replace('<canvas','<details class="data-view"><summary>展开数据图，查看判断依据</summary><canvas').replace('</canvas>','</canvas></details>');return html};
const priorDiversityDraw=Engine.draw.bind(Engine);Engine.draw=function(){priorDiversityDraw();if(labMode)return;let a=$('#activity-stage');if(a){let markup=activityMarkup();a.innerHTML=markup.replace(/^<section[^>]*>/,'').replace(/<\/section>$/,'')}};
function auditRecord(i){let p=Engine.s.train[i],truth=Algo.data('clusters',24,12)[i].c;modal('核对样本 '+(i+1),`<div class="audit-evidence"><span>${p.c?'🍊':'🍏'}</span><div><small>当前训练标签：${p.c?'橘子':'苹果'}</small><h3>原始人工记录：${truth?'橘子':'苹果'}</h3><p>重量特征 ${p.x.toFixed(2)}，甜度特征 ${p.y.toFixed(2)}。这里提供了教学数据的原始类别，供你核对。</p></div></div><button class="primary wide" onclick="repairLabel(${i})">${p.c===truth?'记录一致，返回':'按原始记录纠正标签'}</button>`)}
function repairLabel(i){Engine.s.train[i].c=Algo.data('clusters',24,12)[i].c;guide.ops.add('canvas');closeModal();Engine.draw();refreshGuide()}
function firePrediction(){Engine.s.shot=(Engine.s.shot||0)+1;Engine.s.message='本次落点由当前的斜率与截距计算。调整参数后，可以再试射比较。';Engine.draw()}
function revealExam(){Engine.s.revealTest=true;Engine.draw()}
function treeProbe(x,y){Engine.s.probe={x,y};Engine.draw()}
function manualScan(x,y){let s=Engine.s;if(s.type!=='conv'||x<20||x>212||y<44||y>236)return;let col=Math.max(0,Math.min(5,Math.floor((x-20)/24)-1)),row=Math.max(0,Math.min(5,Math.floor((y-44)/24)-1));s.scanIndex=row*6+col;let k=s.filter==='vertical'?[-1,0,1,-1,0,1,-1,0,1]:s.filter==='horizontal'?[-1,-1,-1,0,0,0,1,1,1]:Array(9).fill(1/9);s.out=Algo.conv(s.img,k);s.scanned=true;guide.ops.add('scan');s.message='取样框覆盖 3×3 像素；每个位置的乘积求和，对应右图中的一个数值。';Engine.draw();refreshGuide()}
function walkManually(a){if(guideBusy||phase===1)return;let s=Engine.s,pos=s.path.length?s.path.at(-1):0,delta=[[-1,0],[0,1],[1,0],[0,-1]][a],x=pos%5+delta[1],y=Math.floor(pos/5)+delta[0],n=y*5+x;let valid=x>=0&&x<5&&y>=0&&y<5&&!s.walls.includes(n);if(!valid)n=pos;s.path=(s.path.length?s.path:[0]).concat(n);s.manualNote=valid?(n===24?'到达终点！回报 '+s.reward:'前进一步，回报 −0.1'):'碰到障碍，留在原地，回报 −0.6';Engine.draw()}
function queueCommand(a){let s=Engine.s;s.queue=(s.queue||[]).concat(a).slice(0,6);Engine.draw()}
function clearCommands(){Engine.s.queue=[];Engine.draw()}
function runCommands(){let s=Engine.s;s.state=0;s.log=[];for(let a of s.queue||[]){if(s.state===3)break;Engine.action('agent'+a);s.log.push(['打开','整理','保存'][a])}s.message=s.state===3?'这组指令完成了任务。接下来让智能体自己学会选择顺序。':'这组顺序还没有完成任务。想想每一步需要什么前提。';Engine.draw()}
const priorActivityRender=renderLesson;renderLesson=function(){priorActivityRender();
 if(phase>0){let bar=$('.worldbar');if(bar&&!labMode)bar.innerHTML=`<span>${PLAY_MODES[current.id-1]}</span><span>${phase===1?'观察阶段':'动手实验'}</span>`;let c=$('#canvas');if(c){let drawing=false,paint=1,coord=e=>{let b=c.getBoundingClientRect();return [(e.clientX-b.left)*520/b.width,(e.clientY-b.top)*320/b.height]};c.addEventListener('pointerdown',e=>{if(!labMode&&(phase===1||guideBusy))return;drawing=true;let [x,y]=coord(e);if(Engine.s.type==='vision'){let i=Math.floor((y-17)/32)*8+Math.floor((x-132)/32);paint=Engine.s.img[i]?0:1}if(Engine.s.type==='conv')manualScan(x,y);if(c.setPointerCapture)c.setPointerCapture(e.pointerId)},true);c.addEventListener('pointermove',e=>{if(!drawing||(!labMode&&guideBusy))return;let [x,y]=coord(e),s=Engine.s;if(s.type==='conv')manualScan(x,y);if(s.type==='vision'){let col=Math.floor((x-132)/32),row=Math.floor((y-17)/32);if(col>=0&&col<8&&row>=0&&row<8){s.img[row*8+col]=paint;s.predicted=false;s.saved=false;Engine.draw()}}});c.addEventListener('pointerup',()=>drawing=false);c.addEventListener('pointercancel',()=>drawing=false)}}};
function acceptMission(){decision=current.answer;nextPhase()}
let activeCase=null;
