 const windows=(x,y,w,h)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="#48747a"/>${Array.from({length:Math.floor(h/15)*2},(_,i)=>`<rect class="city-window" x="${x+8+i%2*14}" y="${y+9+Math.floor(i/2)*15}" width="7" height="7" fill="#bde8b5"/>`).join('')}`;
