const CASE_DEMO_TEXT={city:['播放预警过程','观测到震动 → 快速判断 → 将预警传向城市。示意中波的速度不对应真实时间。'],earth:['播放卫星观测','观测覆盖地表，候选变化区域被标出，随后需要进一步核实。'],wind:['播放风电预测场景','风机发电，预测信息帮助规划供电。动画没有计算真实电量。'],weather:['播放天气演变示意','多种观测进入模型，模型预测后续大气状态。轨迹仅为示意。'],hospital:['播放辅助阅片过程','模型标出候选区域，医生结合完整信息进行评估。这里没有真实医学影像。'],factory:['启动示意生产线','物品经过扫描区，疑似异常被提示复检。这不是实时质检结果。'],protein:['播放结构探索示意','分子信息与模型预测连接起来，帮助提出可验证的研究问题。图形不表示真实蛋白质。'],robot:['播放机器人动作','从观察与训练走向动作执行。这里仅展示任务流程。'],rover:['播放绕障路线','发现挡路岩石 → 更新路线 → 绕行。此动画不使用真实火星导航数据。'],ocean:['播放路线比较示意','考虑后续路段，再选择下一步。这里没有真实海况与航行建议。'],desktop:['播放多步任务','打开资料 → 整理记录 → 保存结果。画面是工作流示意。'],go:['播放局面搜索示意','评估候选落点，再比较后续变化。这里不调用 AlphaGo。'],access:['播放交互设想','识别手势后触发一个操作。实际设计需要和使用者共同测试。']};
function openImpact(id,gallery=false){let c=APPLICATIONS[id-1];activeCase={id,gallery};modal('这项本领，能用在哪里？',`<article class="impact-story"><div class="impact-kicker">${c.domain} <span>${c.tag}</span></div><h2>${c.title}</h2><p class="impact-hook">${c.hook}</p><div id="impact-visual">${impactArt(c)}</div><div class="impact-demo-controls"><button class="primary" onclick="playImpact()">▶ ${CASE_DEMO_TEXT[c.visual][0]}</button><small>应用原理示意 · 非实时数据</small></div><p id="impact-demo-caption" class="impact-demo-caption" aria-live="polite">点击播放，看看这项能力怎样参与一个更大的任务。</p><div class="impact-connection"><span>你刚学到的</span><h3>${LEVELS[id-1].title}</h3><p>${c.bridge}</p></div><ol class="impact-flow">${c.flow.map((t,i)=>`<li><b>${i+1}</b>${t}</li>`).join('')}</ol><details class="impact-boundary"><summary>课堂小模型，怎样走向真实系统？</summary><p>${c.scope}</p>${c.source?`<a href="${CASE_SOURCES[c.source][1]}" target="_blank" rel="noopener noreferrer">查看来源：${CASE_SOURCES[c.source][0]} ↗</a>`:'<p>这是课程设计的应用设想，不指向某个已部署产品。</p>'}</details><div class="impact-next"><button class="primary wide" onclick="finishImpact()">${gallery?'返回应用图鉴':'带着新发现，继续冒险 →'}</button><button class="wide" onclick="closeModal()">留在当前实验</button></div></article>`)}
function playImpact(){let c=APPLICATIONS[activeCase.id-1];$('#impact-visual').innerHTML=impactArt(c,true);$('#impact-demo-caption').textContent=CASE_DEMO_TEXT[c.visual][1]}
function finishImpact(){let c=activeCase;closeModal();if(c.gallery)showImpactGallery();else travelNext()}
function showImpactGallery(){modal('30 项本领，连接真实世界',`<p class="muted">每张卡片都会说明课堂算法与实际应用的联系，也会讲清楚两者的区别。</p><div class="impact-gallery">${APPLICATIONS.map(c=>`<button onclick="openImpact(${c.id},true)"><span>${String(c.id).padStart(2,'0')} · ${c.domain}</span><b>${c.title}</b><small>${progress[c.id]?'✓ 本关已完成':'查看应用方向'} ↗</small></button>`).join('')}</div>`)}
function victoryPiece(){let s=Engine.s;if(s.type==='vision')return `<div class="victory-samples">${s.samples.slice(0,6).map(p=>pixelThumb(p.img,p.c?'#c39169':'#71945d')).join('')}</div>`;if(s.type==='nn')return `<div class="victory-network">${brainVisual()}</div>`;if(s.type==='conv')return `<div class="victory-feature">${Array.from({length:36},(_,i)=>`<span style="background:rgba(65,110,74,${.12+.88*Math.min(1,Math.abs(s.out[i]||0)/3)})"></span>`).join('')}</div>`;if(s.type==='rl')return `<div class="victory-route">${Array.from({length:25},(_,i)=>`<span class="${s.walls.includes(i)?'blocked':s.path.includes(i)?'visited':''}">${i===24?'◆':i===0?'🤖':s.path.includes(i)?'·':''}</span>`).join('')}</div>`;return activityArt(current,'happy')}
const previousChallenge=challenge;challenge=function(){previousChallenge();if(phase===3&&Engine.s.last?.pass){let r=Engine.s.last,c=APPLICATIONS[current.id-1],before=guide.before,after=Engine.metric();modal('挑战完成',`<div class="varied-victory">${victoryPiece()}</div><h2 class="resulttitle">${['这次分对了！','预测更准了！','模型学到了新规律！','图像实验完成！','小芽学会行动了！','你的作品又前进了一步！'][current.chapter]}</h2><p>${esc(r.detail)}</p>${before&&after?`<div class="before-after"><div>调整前<b>${before.format==='mse'?before.value.toFixed(3):Math.round(before.value*100)+'%'}</b></div><span>→</span><div>调整后<b>${after.format==='mse'?after.value.toFixed(3):Math.round(after.value*100)+'%'}</b></div></div>`:''}<button class="impact-teaser" onclick="openImpact(${current.id})"><span>${c.domain} · 从这一关出发</span><strong>${c.title}</strong><p>${c.bridge}</p><b>看看它在现实中能做什么 ↗</b></button><div class="victory-actions"><button class="primary wide" onclick="openImpact(${current.id})">进入现实应用场景 →</button><button onclick="closeModal();travelNext()">继续下一关</button></div>`)}};
const earlierInventory=inventory;inventory=function(){earlierInventory();let app=$('#app');app.innerHTML=app.innerHTML.replace('<div class="footer">','<div class="application-portal"><h3>我学到的本领能做什么？</h3><p>从城市预警到深空探索，查看 30 个现实应用连接。</p><button class="primary" onclick="showImpactGallery()">打开应用图鉴 ↗</button></div><div class="footer">')};
const previousHome=home;home=function(){previousHome();let app=$('#app');app.innerHTML=app.innerHTML.replace('<div class="introstrip">','<div class="application-portal"><span class="eyebrow">从课堂走向真实世界</span><h3>这些小实验，通向怎样的大问题？</h3><p>保护森林、预测风电、辅助科研、探索火星……每关之后，都有一个新的应用场景。</p><button class="secondary" onclick="showImpactGallery()">先看看这些本领的用途 ↗</button></div><div class="introstrip">')};
home();
